INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'At Night: The Nurse', 'At Night is an episodic psychological horror game presented as a late-night television program, where each episode features a survivor recounting a traumatic event. In this episode, The Nurse, you follow Emily Collins, a nurse who takes a late-night job at Bloomring Hospital. What begins as a routine shift quickly turns unsettling as the hospital reveals something is wrong.' FROM games WHERE igdb_id = 388279 ON CONFLICT (game_id, language_code) DO NOTHING;
