INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweet Starlight Sisters', '“Sweet Starlight Sisters” is a character-raising romance adventure where you share a sweet life under one roof with the bunny-girl sisters Anya and Sanya. Train the duo with your own hands to become top performers, and—while occasionally fielding their heart-pounding advances—lead them to victory.' FROM games WHERE igdb_id = 378897 ON CONFLICT (game_id, language_code) DO NOTHING;
