INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jin', 393528, '2026-03-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobp4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hsv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jin', 'JIN is a traditional inspired strategy board game built on simple rules but layered with deep tactical decision making. Players move pieces across the board, stack them to increase value, and capture opponents by landing with equal or lower strength, turning every move into a calculated risk. The neutral zone mechanics add tension in the center of the board, forcing smart positioning and long term planning. With clean visuals, fast turn based gameplay, and a strong focus on skill over luck, JIN rewards players who think ahead, set traps, and control the board with precision.' FROM games WHERE igdb_id = 393528 ON CONFLICT (game_id, language_code) DO NOTHING;
