INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rakka: Wake 01 - Soot', 'A visual novel paired with point-and-click elements, Rakka distinguishes itself with its breadth of hand-drawn assets, detailed backgrounds, charming character art, and unique paper-cut style. Complimented by the art is the incredible original soundtrack; spearheaded by the minds behind The PMT, it oozes indie charm. Both serve in tandem, dragging the player into the character and dialogue driven world of Rakka. Think you can make it to its thrilling conclusion?' FROM games WHERE igdb_id = 341302 ON CONFLICT (game_id, language_code) DO NOTHING;
