INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hero of Destiny Was Killed by the Final Boss', 'How many NPCs equal 1 Hero? In the land of Alta, The Hero of Destiny was fated to defeat a terrible Dark Wizard... but the Hero of Destiny was killed by the final boss. What now? Next to the final dungeon, in a sleepy village, 50 NPCs decide to take matters into their own hands.' FROM games WHERE igdb_id = 386940 ON CONFLICT (game_id, language_code) DO NOTHING;
