INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcanus Online', 'Arcanus Online is a 2D medieval fantasy MMORPG with pixel art aesthetics, where players can explore vast lands, battle monsters, complete quests, and interact with others in a classic retro-style online world. Developed in Visual Basic 6 with DirectX 7, the game preserves the nostalgic feel of early 2000s MMOs while offering a persistent online universe. Players can customize their characters, craft items, join guilds, and participate in real-time PvP and PvE adventures.' FROM games WHERE igdb_id = 351054 ON CONFLICT (game_id, language_code) DO NOTHING;
