INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit Vendor', 'I built Spirit Vendor as a solo indie dev, and I''m excited to share it with you! In this charming world, you decide how your day unfolds—run your shop, tend your fields, and care for your animals. Explore a lively village, meet unique characters, build friendships, and perhaps even find true love.' FROM games WHERE igdb_id = 374618 ON CONFLICT (game_id, language_code) DO NOTHING;
