INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bus Simulator: World Tour', 'Bus Simulator: World Tour delivers the ultimate bus‑driving experience with realistic mechanics, detailed environments, and a massive fleet of vehicles. Travel the world behind the wheel of 30 unique buses across 14 real‑life inspired locations and complete 140 routes packed with variety and challenge. Customize your ride, explore freely, and enjoy a true next‑generation Bus Simulator built for immersion.' FROM games WHERE igdb_id = 388620 ON CONFLICT (game_id, language_code) DO NOTHING;
