INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Night', 'A single-player exploration/scavenger hunt game set in a haunted forest where the player searches for a missing key needed to unlock a remote cabin. The key spawns in different areas each playthrough and roaming spirits must be avoided while discovering landmarks and hidden locations, including an underground cave. Difficulty settings along with tracked run statistics encourage players to improve their times and complete repeated runs.' FROM games WHERE igdb_id = 394039 ON CONFLICT (game_id, language_code) DO NOTHING;
