INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Day I Became a Bird', 'Join Frank, an awkward young boy, as he discovers newfound feelings for his classmate, Sylvia - who only has eyes for birds. Explore, collect, and solve puzzles as Frank attempts to catch her attention with a homespun, feathery transformation in this warm and nostalgic return to childhood.' FROM games WHERE igdb_id = 390967 ON CONFLICT (game_id, language_code) DO NOTHING;
