INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Tithe for Olaf', 'A grimly humorous single-player tower defense roguelite set in 17th-century Norway. Defend your farm from the King’s tax collectors, build bizarre towers, and lead a farmer’s uprising as a goat-riding rebel! Upgrade your farm, manage resources, and weaponize onions in escalating rural chaos.' FROM games WHERE igdb_id = 366044 ON CONFLICT (game_id, language_code) DO NOTHING;
