INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kumasama', 'A large brown shadow lurks in the abandoned factory; the night hides her form.Something terrifyingly massive is concealed within this town.I think of her, and of the days I can never go back to.“KUMASAMA” is a horror adventure set in the present day.' FROM games WHERE igdb_id = 382730 ON CONFLICT (game_id, language_code) DO NOTHING;
