INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sublevel 9', 'In a neighborhood where all the houses are identical, something is wrong. You wake up on a silent street, surrounded by identical houses, with no memory of how you got there. No cars pass, there are no neighbors, and every door seems to hide more than just empty walls. Streets repeat. Houses change. And something is watching you.' FROM games WHERE igdb_id = 393315 ON CONFLICT (game_id, language_code) DO NOTHING;
