INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Ties Isekaijoucho Träumerei', 'Our protagonist, Kirishima Yu, returns from Tokyo to the island where he once lived and reunites with his childhood friend, Minase Seikai. Seikai, who had been on the verge of giving up on her dream of becoming an idol, looks somewhat gloomy. Wanting to make her smile again, Yu proposes that she debut as a virtual idol named "Isekaijoucho" based on an illustration he drew himself.' FROM games WHERE igdb_id = 376085 ON CONFLICT (game_id, language_code) DO NOTHING;
